"""Generate docs/analyses.md and docs/graphs.md from the registries."""
from pathlib import Path

from analysis_ui.core import registry
from analysis_ui.graphs import GRAPHS
from analysis_ui.graphs import registry as gr
from analysis_ui.graphs import style

registry.discover()
DOCS = Path(__file__).resolve().parent.parent / "docs"

lines = ["# Analyses", "",
         f"{sum(1 for a in registry.ANALYSES.values() if not a.id.startswith('_'))} analyses. "
         "Generated by `scripts/make_docs.py` — do not edit by hand.", ""]
for cat in registry.CATEGORIES:
    items = [a for a in registry.ANALYSES.values() if a.category == cat and not a.id.startswith("_")]
    if not items:
        continue
    lines += [f"## {cat}", "", "| Analysis | Engine | What it does |", "|---|---|---|"]
    for a in items:
        lines.append(f"| **{a.name}** <br>`{a.id}` | {'R' if a.engine == 'r' else 'Python'} | {a.description} |")
    lines.append("")
(DOCS / "analyses.md").write_text("\n".join(lines), encoding="utf-8")

lines = ["# Graph types", "",
         f"{len(GRAPHS)} graph types, each drawn by either engine (matplotlib or ggplot2). "
         "Generated by `scripts/make_docs.py` — do not edit by hand.", ""]
for cat in gr.CATEGORIES:
    items = [g for g in GRAPHS.values() if g.category == cat]
    if not items:
        continue
    lines += [f"## {cat}", "", "| Graph | What it shows | Type-specific options |", "|---|---|---|"]
    for g in items:
        own = [o["label"] for o in g.options if o.get("section") not in
               ("Data", "Titles & labels", "Colors & theme", "Axes", "Legend", "Fonts", "Size", None)]
        lines.append(f"| **{g.name}** <br>`{g.id}` | {g.description} | {', '.join(own[:14])}{' …' if len(own) > 14 else ''} |")
    lines.append("")
lines += ["## Look-and-feel options shared by every graph", ""]
sections: dict[str, list[str]] = {}
for o in style.style_options({"axes", "x_num", "y_num", "x_cat", "legend", "palette", "colormap", "flip"}):
    sections.setdefault(o["section"], []).append(o["label"])
for s, labels in sections.items():
    lines.append(f"* **{s}** — {', '.join(labels)}")
lines += ["", "Themes: " + ", ".join(t["label"] for t in style.themes()) + ".", "",
          "Palettes: " + ", ".join(p["label"] for p in style.palettes()["palettes"]) + ".", "",
          "Color scales: " + ", ".join(p["label"] for p in style.palettes()["colormaps"]) + ".", ""]
(DOCS / "graphs.md").write_text("\n".join(lines), encoding="utf-8")
print("docs written")
